.award-card{
    width:200px;
    padding:18px;
    text-align:center;
    border-radius:15px;
    background:#0f4c81;
    color:#d4af37;
    box-shadow:0 5px 15px rgba(0,0,0,0.15);
    transition:0.3s ease;
    cursor:pointer;
}

.award-card h3{
    margin:10px 0 6px;
    font-size:20px;
    color:#fff;
}

.award-card p{
    font-size:14px;
    color:#fff;
}

.award-card img{
    transition:0.3s ease;
}

/* Hover Effect */
.award-card:hover{
    transform:translateY(-8px) scale(1.03);
    box-shadow:0 12px 25px rgba(0,0,0,0.25);
}

.award-card:hover img{
    transform:rotate(8deg) scale(1.1);
}



.test{
background: linear-gradient(135deg, #f5f7fa, #dfe7f2);
    padding: 18px 20px;
    cursor: pointer;
    position: relative;
    font-size: 15px;
    font-weight: 300;
    color: #1f5fa9;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    border-bottom: 1px solid #ddd;
}



.convocation-wrapper{
    width: 100%;
    margin: 20px auto;
    font-family: Arial, Helvetica, sans-serif;
}

.convocation-card{
    background: #fff;
    border-radius: 12px;
    overflow: hidden;
    margin-bottom: 20px;
    box-shadow: 0 4px 15px rgba(0,0,0,0.08);
    border: 1px solid #e5e5e5;
    transition: 0.3s ease;
}

.convocation-card:hover{
    transform: translateY(-3px);
    box-shadow: 0 6px 18px rgba(0,0,0,0.12);
}

.accordion{
    background: linear-gradient(135deg,#f5f7fa,#dfe7f2);
    padding: 18px 20px;
    cursor: pointer;
    position: relative;
    font-size: 15px;
    font-weight: 300;
    color: #1f5fa9;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    border-bottom: 1px solid #ddd;
}

.accordion:after{
    content: '+';
    position: absolute;
    right: 20px;
    top: 14px;
    font-size: 28px;
    color: #666;
}

.accordion.active:after{
    content: '-';
}

.panel{
    display: none;
    padding: 20px;
    background: #fff;
}
.panel{
    max-height:0;
    overflow:hidden;
    transition:max-height 0.4s ease;
}
.program-grid{
    display: flex;
    flex-wrap: wrap;
    gap: 15px;
}

.program-box{
    flex: 1 1 calc(33.33% - 15px);
    min-width: 240px;
}

.program-link{
    display: block;
    padding: 15px 18px;
    border-radius: 10px;
    background: #f7f9fc;
    border: 1px solid #dbe4f0;
    text-decoration: none;
    color: #222;
    font-size: 15px;
    font-weight: 600;
    transition: all 0.3s ease;
}

.program-link i{
    color: #1f5fa9;
    margin-right: 10px;
}

.program-link:hover{
    background: #1f5fa9;
    color: #fff;
    transform: translateY(-2px);
}

.program-link:hover i{
    color: #fff;
}

.special-link{
    display:block;
    text-align:center;
    padding:18px;
    background: linear-gradient(135deg,#1f5fa9,#3b7dd8);
    color:#fff;
    border-radius:12px;
    font-size:20px;
    font-weight:700;
    text-decoration:none;
    margin-bottom:20px;
    transition:0.3s;
}

.special-link:hover{
    transform:scale(1.02);
    color:#fff;
}

@media(max-width:768px){

    .accordion{
        font-size:18px;
        padding:15px;
    }

    .program-box{
        flex: 1 1 100%;
    }

    .program-link{
        font-size:15px;
    }
}
.panel{
    display:none;
    padding:20px;
    background:#fff;
}

.accordion.active + .panel{
    display:block;
}








