.award-card{
    width:200px;
    padding:18px;
    text-align:center;
    border-radius:15px;
    background:#0f4c81;
    color:#d4af37;
    box-shadow:0 5px 15px rgba(0,0,0,0.15);
    transition:0.3s ease;
    cursor:pointer;
}

.award-card h3{
    margin:10px 0 6px;
    font-size:20px;
    color:#fff;
}

.award-card p{
    font-size:14px;
    color:#fff;
}

.award-card img{
    transition:0.3s ease;
}

/* Hover Effect */
.award-card:hover{
    transform:translateY(-8px) scale(1.03);
    box-shadow:0 12px 25px rgba(0,0,0,0.25);
}

.award-card:hover img{
    transform:rotate(8deg) scale(1.1);
