:root{
  --cb:#0c4d8b;
  --cb-dark:#083a6a;
  --cb-mid:#1a6bbf;
  --cb-light:#d6e8f7;
  --cb-xlight:#eef5fd;
  --gold:#D98600;
  --gold-dk:#b37000;
  --gold-light:#fff8e6;
  --gold-pale:#fffbf0;
  --bg:#f7faff;
  --border:#dce8f5;
  --text:#000000;
  --shadow-sm:0 2px 8px rgba(12,77,139,.06);
  --shadow:0 6px 20px rgba(12,77,139,.08);
  --shadow-md:0 10px 30px rgba(12,77,139,.12);
  --r:14px;
}
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:'DM Sans',sans-serif;color:var(--text);background:#fff;line-height:1.75;font-size:15px}
p{text-align:justify;color:var(--text);margin:0}
p+p{margin-top:14px}
strong{font-weight:700}
.wrap{margin:auto;padding:36px 28px 60px}


.sh{margin:52px 0 22px}
.sh-first{margin-top:0}
.eyebrow{display:flex;align-items:center;gap:10px;margin-bottom:9px}
.eyebrow-line{height:2px;width:28px;background:var(--gold);border-radius:2px;flex-shrink:0}
.eyebrow-text{font-size:.7rem;font-weight:700;letter-spacing:.13em;text-transform:uppercase;color:var(--gold)}
h2{color:#0c4d8b;font-size:clamp(1.55rem,2.6vw,2rem);font-weight:700;line-height:1.2;position:relative;display:inline-block}
h2::after{content:"";display:block;height:3px;width:72px;background:var(--gold);border-radius:2px;margin-top:9px;transition:width .3s}
h2:hover::after{width:110px}


.divider{display:flex;align-items:center;gap:0;margin:50px 0 0;height:18px;overflow:hidden}
.divider-bar{flex:1;height:1px;background:var(--border)}
.divider-diamond{width:8px;height:8px;background:var(--gold);transform:rotate(45deg);flex-shrink:0;margin:0 10px}
.divider-dot{width:4px;height:4px;background:#f0d890;border-radius:50%;flex-shrink:0;margin:0 5px}

.about-hero{background:var( --cb-dark);border-radius:var(--r);padding:28px 32px 24px;margin-bottom:0;position:relative;overflow:hidden}
.about-hero::before{content:"";position:absolute;right:-40px;top:-40px;width:200px;height:200px;border-radius:50%;background:rgba(255,255,255,.12);pointer-events:none}
.about-hero::after{content:"";position:absolute;right:30px;bottom:-50px;width:130px;height:130px;border-radius:50%;background:rgba(255,255,255,.04);pointer-events:none}
.about-quote{font-size:clamp(1rem,1.8vw,1.2rem);font-weight:600;font-style:italic;color:#fff;line-height:1.65;text-align:left;position:relative;z-index:1;padding-left:20px;border-left:3px solid rgba(255,255,255,.5)}
.about-body{background:var(--bg);border:1px solid var(--border);border-top:none;border-radius:0 0 var(--r) var(--r);padding:26px 30px 22px}
.about-body p{font-size:.95rem;line-height:1.8}
.chips-label{font-size:.7rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--gold-dk);margin:18px 0 9px}
.chips{display:flex;flex-wrap:wrap;gap:7px}
.chip{background:var(--gold-light);border:1.5px solid #f0d890;color:var(--gold-dk);font-size:.78rem;font-weight:600;padding:4px 14px;border-radius:20px;letter-spacing:.02em}


.team-card{display:flex;align-items:center;gap:20px;padding:20px 26px;background:var(--bg);border:1px solid var(--border);border-left:4px solid var(--cb-dark);border-radius:var(--r);box-shadow:var(--shadow-sm)}
.avatar{width:58px;height:58px;border-radius:50%;background:var(--gold);color:#fff;font-size:1.2rem;font-weight:700;display:flex;align-items:center;justify-content:center;flex-shrink:0;border:3px solid #f0d890}
.t-name{font-size:1.05rem;font-weight:700;color:#1a1a1a;margin-bottom:5px}
.t-chip{display:inline-block;background:var(--gold-light);border:1px solid #f0c84a;color:#7a4800;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em;padding:3px 11px;border-radius:20px;margin-bottom:5px}
.t-dept{font-size:.85rem;color:#444}

.vm-row{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.vm-card{background:var(--gold-pale);border:1px solid #f0d890;border-left:4px solid var(--gold);border-radius:var(--r);padding:24px 26px;position:relative}
.vm-label{font-size:.68rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--gold-dk);margin-bottom:6px}
.vm-qmark{font-size:2.8rem;line-height:.8;color:var(--gold);font-family:Georgia,serif;display:block;margin-bottom:8px;opacity:.6}
.vm-text{font-size:.92rem;line-height:1.8;color:var(--text);text-align:justify}

.obj-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.obj-card{background:var(--bg);border:1px solid var(--border);border-radius:var(--r);padding:20px 22px;display:flex;gap:14px;align-items:flex-start;box-shadow:var(--shadow-sm);transition:.22s}
.obj-card:hover{box-shadow:var(--shadow-md);transform:translateY(-3px);border-color:#f0d890}
.obj-ico{width:42px;height:42px;border-radius:10px;background:var(--gold);display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:1px}
.obj-body{}
.obj-title{font-size:.95rem;font-weight:700;color:#1a1a1a;margin-bottom:5px}
.obj-desc{font-size:.85rem;color:var(--text);line-height:1.65;text-align:justify}

.event-card{display:flex;gap:18px;align-items:flex-start;background:var(--bg);border:1px solid var(--border);border-radius:var(--r);padding:20px 24px;box-shadow:var(--shadow-sm);margin-bottom:14px;transition:.22s}
.event-card:hover{box-shadow:var(--shadow-md);border-color:#f0d890}
.ev-num{width:40px;height:40px;border-radius:50%;background:var( --cb-dark);color:#fff;font-size:.95rem;font-weight:700;display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:1px;border:2px solid #f0d890}
.ev-title{font-size:1rem;font-weight:700;color:#1a1a1a;margin-bottom:6px}
.ev-desc{font-size:.88rem;color:var(--text);line-height:1.7;text-align:justify}
.mail-row{display:flex;align-items:center;gap:14px;margin-top:18px;padding:13px 18px;background:var(--gold-light);border:1px solid #f0d890;border-radius:10px}
.mail-ico{width:34px;height:34px;border-radius:50%;background:var(--gold);display:flex;align-items:center;justify-content:center;flex-shrink:0}
.mail-label{font-size:.68rem;font-weight:700;text-transform:uppercase;letter-spacing:.09em;color:var(--gold-dk);margin-bottom:2px}
.mail-val{font-size:.9rem;font-weight:600;color:var(--text)}

@media(max-width:640px){
  .vm-row,.obj-grid{grid-template-columns:1fr}
  .team-card{flex-direction:column;align-items:flex-start}
}



