    box-shadow: 0 6px 18px rgba(0,0,0,0.12);
}

.accordion{
    background: linear-gradient(135deg,#f5f7fa,#dfe7f2);
    padding: 18px 20px;
    cursor: pointer;
    position: relative;
    font-size: 15px;
    font-weight: 300;
    color: #1f5fa9;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    border-bottom: 1px solid #ddd;
}

.accordion:after{
    content: '+';
    position: absolute;
