}

.program-link i{
    color: #1f5fa9;
    margin-right: 10px;
}

.program-link:hover{
    background: #1f5fa9;
    color: #fff;
    transform: translateY(-2px);
}

.program-link:hover i{
    color: #fff;
}

.special-link{
    display:block;
    text-align:center;
    padding:18px;
    background: linear-gradient(135deg,#1f5fa9,#3b7dd8);
    color:#fff;
    border-radius:12px;
    font-size:20px;
    font-weight:700;
    text-decoration:none;
    margin-bottom:20px;
    transition:0.3s;
}

.special-link:hover{
    transform:scale(1.02);
    color:#fff;
}

